<?php $heading='Pengajuan PBG'; $top_actions='<a class="btn btn-primary" href="'.base_url('pengajuan-pbg/tambah').'">+ Tambah Pengajuan</a>'; $this->load->view('pbg_pu/header',compact('heading','top_actions','nama_pengguna')); ?>
<?php if($this->session->flashdata('sukses')):?><div class="notice"><?= htmlspecialchars($this->session->flashdata('sukses')) ?></div><?php endif;?>
<div class="card"><div style="display:flex;justify-content:flex-end;margin-bottom:28px"><input class="search" id="q" placeholder="Cari nama pemohon atau alamat..."></div><div class="table-wrap"><table id="table"><thead><tr><th>Jenis</th><th>No. Permohonan</th><th>Nama Pemohon</th><th>Alamat</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php if(empty($daftar)):?><tr><td colspan="7">Belum ada pengajuan. Klik <b>+ Tambah Pengajuan</b> untuk mulai.</td></tr><?php endif;?>
<?php foreach($daftar as $r):?><tr><td><span class="badge diajukan">PBG</span></td><td><?= htmlspecialchars($r['no_permohonan']) ?></td><td><?= htmlspecialchars($r['nama_pemohon']) ?></td><td><?= htmlspecialchars($r['alamat_bangunan']) ?></td><td><?= date('d/m/Y',strtotime($r['created_at'])) ?></td><td><span class="badge <?= $r['status'] ?>"><?= ucfirst($r['status']) ?></span></td><td><div class="actions"><a class="btn" href="<?= base_url('pengajuan-pbg/tahap/'.$r['id']) ?>">Lihat Tahap</a><?php if($r['status']==='diajukan'):?><a class="btn" href="<?= base_url('pengajuan-pbg/edit/'.$r['id']) ?>">Edit</a><a class="btn btn-danger" onclick="return confirm('Hapus pengajuan ini?')" href="<?= base_url('pengajuan-pbg/hapus/'.$r['id']) ?>">Hapus</a><?php else:?><span style="color:#82939c;padding:13px">Terkunci</span><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div>
<script>q.oninput=()=>{let x=q.value.toLowerCase();document.querySelectorAll('#table tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(x)?'':'none')}</script>
